];

const filteredData = logData.filter(
  (line) => line.trim().startsWith("2025-06-19T") && line.includes("T09:") &&!line.startsWith("#")
);

const requests = filteredData.map((line) => {
  const [timestamp, method, path, status, latency] = line.split(" ");
  return {
    timestamp,
    method,
    path,
    status,
    latency,
  };
});

const result = requests.reduce(
  (acc, req) => {
    if (!acc[req.path]) acc[req.path] = {};
    if (!acc[req.path][req.status]) acc[req.path][req.status] = 0;
    acc[req.path][req.status]++;
    return acc;
  },
  {}
);

Object.keys(result).forEach((path) => {
  Object.keys(result[path]).forEach((status) => {
    if (result[path][status] === 0) delete result[path][status];
  });
  if (Object.keys(result[path]).length === 0) delete result[path];
});

